const {chromium}=require('playwright');const F='file://'+process.argv[2];const S=process.argv[3];
const ok=(c,m)=>console.log((c?'PASS ':'FAIL ')+m);
(async()=>{const b=await chromium.launch();const p=await b.newPage({viewport:{width:1440,height:900}});const e=[];p.on('pageerror',x=>e.push(x.message));
await p.goto(F);await p.evaluate(()=>{localStorage.clear();localStorage.setItem('scopeline-chat-v1',JSON.stringify({features:[],view:'home',mode:'steps'}))});await p.reload();await p.waitForTimeout(400);
await p.click('[data-menu="product"]');ok(await p.locator('#mm-product').isVisible(),'Product menu opens');
await p.screenshot({path:S+'/nav-product.png'});
await p.keyboard.press('Escape');ok(await p.locator('#mm-product').isHidden(),'Escape closes it');
await p.click('[data-menu="res"]');ok(await p.locator('#mm-res').isVisible(),'Resources menu opens');await p.screenshot({path:S+'/nav-res.png'});
await p.click('h1');ok(await p.locator('#mm-res').isHidden(),'clicking outside closes it');
await p.click('[data-menu="product"]');await p.click('#mm-product [data-try="uc_growth"]');await p.waitForSelector('.m-ai');
ok((await p.textContent('.m-user')).includes('I lead growth'),'use case opens the chat with a role starter');
ok((await p.locator('.m-ai').first().textContent()).includes('After you agree'),'growth starter is answered with baseline and test steps');
await p.click('[data-act="home"]');await p.click('[data-menu="res"]');await p.click('#mm-res a[href="#faq"]');await p.waitForTimeout(700);
ok(await p.locator('#mm-res').isHidden(),'resource link closes the menu');
const m=await b.newPage({viewport:{width:390,height:844}});await m.goto(F);await m.waitForTimeout(400);
await m.click('[data-act="mobmenu"]');await m.click('[data-menu="product"]');await m.waitForTimeout(200);
ok(await m.locator('#mm-product').isVisible(),'mobile menu shows the product menu');
ok(!(await m.evaluate(()=>document.documentElement.scrollWidth>innerWidth)),'fits a phone with the menu open');
await m.screenshot({path:S+'/nav-mobile.png'});
ok(e.length===0,'no errors '+e.join('; '));await b.close();})();
